
import { Fragment, useCallback, useEffect, useRef, useState, type FormEvent, type ReactNode } from "react";
import { AlertTriangle, ArrowRightLeft, Brush, ArrowDownToLine, ArrowLeft, ArrowRight, ArrowUpRight, Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, Circle, CircleCheck, Clock3, Coffee, Flower2, History, LayoutDashboard, Leaf, ListTodo, LoaderCircle, LogOut, Moon, MoreHorizontal, Plus, Repeat2, Search, Settings2, ShieldCheck, Sparkles, Sprout, Sun, Trash2, Users, X } from "lucide-react";

import { readChecklist, temperatureLabels, type ChecklistMeta } from "@/lib/checklist-types";
import { loginRedirect } from "@/lib/login-url";

type User = { id:string; name:string; role:"admin"|"employee"; active:number };
type Task = {id:string;title:string;description:string;day:string;time:string;category:string;priority:string;assignee_id:string|null;assignee_name:string|null;status:string;completed_name:string|null;completed_at:string|null;completed_by:string|null;note:string;version:number;recurrence_id:string|null;checklist_meta:string|null;values_json:string|null};
type Routine = {id:string;title:string;description:string;time:string;category:string;priority:string;assignee_id:string|null;assignee_name:string|null;weekdays:number;starts_on:string;ends_on:string|null;active:number;version:number;checklist_meta:string|null};
type Event = {id:string;task_id:string|null;actor_id:string;actor_name:string;action:string;title:string;note:string;created_at:string};
type Data = {user:User;tasks:Task[];members:User[];events:Event[];routines:Routine[];cafeName:string;publicUrl?:string};
type Page = "today"|"tasks"|"team"|"history"|"settings"|"routines";
const categories = [{id:"opening",name:"Otwarcie kawiarni",small:"Otwarcie",icon:Sun,color:"peach"},{id:"day",name:"W trakcie dnia",small:"W ciągu dnia",icon:Coffee,color:"sage"},{id:"handover",name:"Przekazanie zmiany",small:"Przekazanie",icon:ArrowRightLeft,color:"sage"},{id:"closing",name:"Zamknięcie kawiarni",small:"Zamknięcie",icon:Moon,color:"lavender"},{id:"weekly_cleaning",name:"Porządki tygodniowe",small:"Tygodniowe",icon:Brush,color:"peach"}];
const weekdaysList=[{label:"Pon",bit:2},{label:"Wt",bit:4},{label:"Śr",bit:8},{label:"Czw",bit:16},{label:"Pt",bit:32},{label:"Sob",bit:64},{label:"Nd",bit:1}];
function scheduleLabel(mask:number){if(mask===127)return "Codziennie";if(mask===62)return "Pon.–pt.";if(mask===65)return "Sob.–nd.";return weekdaysList.filter(d=>mask&d.bit).map(d=>d.label).join(", ");}
const actionLabels:Record<string,string>={problem_reported:"Zgłoszono problem",created:"Dodano zadanie",completed:"Wykonano zadanie",started:"Rozpoczęto zadanie",reopened:"Cofnięto wykonanie",updated:"Zmieniono zadanie",deleted:"Usunięto zadanie",member_added:"Dodano pracownika",member_updated:"Zmieniono konto",member_disabled:"Dezaktywowano konto",member_enabled:"Aktywowano konto",settings_updated:"Zmieniono ustawienia",routine_created:"Dodano cykl",routine_updated:"Zmieniono cykl",routine_paused:"Wstrzymano cykl",routine_resumed:"Wznowiono cykl"};
function today() { return new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Warsaw",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date()); }
function dateLabel(day:string,options:Intl.DateTimeFormatOptions={day:"numeric",month:"long"}) { return new Date(day+"T12:00:00").toLocaleDateString("pl-PL",options); }
function dateTime(date:string) { return new Date(date).toLocaleString("pl-PL",{timeZone:"Europe/Warsaw",day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}); }
function shortTime(date:string) { return new Date(date).toLocaleTimeString("pl-PL",{timeZone:"Europe/Warsaw",hour:"2-digit",minute:"2-digit"}); }
function initials(name:string) { return name.trim().split(/\s+/).map(s=>s[0]).slice(0,2).join("").toUpperCase(); }
async function api(path:string,method="GET",data?:unknown) {
  const res=await fetch(new URL("api/"+path,document.baseURI),{method,cache:"no-store",headers:method!=="GET"?{"Content-Type":"application/json"}:{},...(data?{body:JSON.stringify(data)}:{})});
  const result=await res.json().catch(()=>({error:"Brak połączenia z serwerem."})) as Data & {error?:string;relogin?:boolean};
  if(!res.ok) throw Object.assign(new Error(result.error||"Nie udało się wykonać operacji."),{status:res.status}); return result;
}
function Brand({small=false}:{small?:boolean}) { return <div className={"brand "+(small?"brand-small":"")}><span className="brand-mark"><Sprout size={small?22:28} strokeWidth={1.5}/></span><div><span className="brand-name">cafe flore<span className="brand-dot">.</span></span></div></div>; }
function Avatar({name,large=false}:{name:string;large?:boolean}) { return <span className={"avatar "+(large?"avatar-lg":"")} style={{"--avatar-color":["#e8eddf","#f2e4d7","#e7e5ef","#dce8e5"][name.charCodeAt(0)%4]} as React.CSSProperties}>{initials(name)}</span>; }
function Empty({icon:Icon=ListTodo,title,children}:{icon?:typeof ListTodo;title:string;children:ReactNode}) { return <div className="empty"><span className="empty-icon"><Icon size={27} strokeWidth={1.4}/></span><h3>{title}</h3><p>{children}</p></div>; }
function Modal({title,subtitle,children,onClose}:{title:string;subtitle?:string;children:ReactNode;onClose:()=>void}) {
  const ref=useRef<HTMLDivElement>(null); const closeRef=useRef(onClose);closeRef.current=onClose;
  useEffect(()=>{const before=document.activeElement as HTMLElement; const old=document.body.style.overflow; document.body.style.overflow="hidden"; const el=ref.current;const firstFocus=el?.querySelector<HTMLElement>("[data-autofocus]")||el?.querySelector<HTMLElement>("input,button,select,textarea");firstFocus?.focus(); const key=(e:KeyboardEvent)=>{if(e.key==="Escape")closeRef.current();if(e.key==="Tab"&&el){const items=Array.from(el.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]'));const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}};document.addEventListener("keydown",key);return()=>{document.body.style.overflow=old;document.removeEventListener("keydown",key);before?.focus();};},[]);
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" ref={ref}><header><div><h2 id="modal-title">{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-button" aria-label="Zamknij okno" onClick={onClose}><X size={20}/></button></header>{children}</div></div>;
}

export default function CafeApp() {
  const [user,setUser]=useState<User|null>(null); const [initial,setInitial]=useState(true); const [cafeName,setCafeName]=useState("Cafe Flore");
  const [pin,setPin]=useState(""); const [loginError,setLoginError]=useState(""); const [busy,setBusy]=useState(false); const [loading,setLoading]=useState(false);
  const [data,setData]=useState<Data|null>(null); const [page,setPage]=useState<Page>("today"); const [selectedDay,setSelectedDay]=useState(today); const [status,setStatus]=useState("all"); const [category,setCategory]=useState("all"); const [person,setPerson]=useState("all"); const [query,setQuery]=useState("");
  const [toast,setToast]=useState(""); const [error,setError]=useState(""); const [taskModal,setTaskModal]=useState<Task|"new"|null>(null); const [memberModal,setMemberModal]=useState<User|"new"|null>(null); const [temperatureTask,setTemperatureTask]=useState<Task|null>(null); const [deleteTask,setDeleteTask]=useState<Task|null>(null); const [historyFilter,setHistoryFilter]=useState("all"); const requestId=useRef(0);
  const [routineModal,setRoutineModal]=useState<Routine|"new"|null>(null);
  const [problemTask,setProblemTask]=useState<Task|null>(null);
  const admin=user?.role==="admin";
  useEffect(()=>{
    let redirecting=false;
    api("auth").then(r=>{
      const target=loginRedirect(r.publicUrl,window.location.href);
      if(target){window.location.replace(target);redirecting=true;return;}
      setUser(r.user);setCafeName(r.cafeName);
    }).catch(e=>setLoginError(e.message)).finally(()=>{if(!redirecting)setInitial(false);});
  },[]);
  useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(""),4000);return()=>clearTimeout(timer);},[toast]);
  const load=useCallback(async(quiet=false)=>{
    const id=++requestId.current;if(!quiet)setLoading(true);
    try {const r=await api("data?day="+selectedDay);if(id!==requestId.current)return;setData(r);setUser(r.user);setCafeName(r.cafeName);setError("");}
    catch(e){if(id!==requestId.current)return;const err=e as Error&{status?:number};if(err.status===401){setUser(null);setData(null);}else setError(err.message);}
    finally{if(id===requestId.current)setLoading(false);}
  },[selectedDay]);
  useEffect(()=>{if(!user?.id)return;load();const interval=setInterval(()=>{if(!document.hidden)load(true);},30000);const focus=()=>load(true);window.addEventListener("focus",focus);return()=>{requestId.current++;clearInterval(interval);window.removeEventListener("focus",focus);};},[user?.id,load]);
  async function login(e:FormEvent){e.preventDefault();if(busy)return;setBusy(true);setLoginError("");try{const r=await api("auth","POST",{pin});setUser(r.user);setPin("");setPage("today");setToast("Zalogowano.");}catch(e){setLoginError((e as Error).message);}finally{setBusy(false);}}
  async function logout(){try{await api("auth","DELETE",{});requestId.current++;setUser(null);setData(null);setPin("");setPage("today");setStatus("all");setCategory("all");setPerson("all");setQuery("");}catch(e){setError((e as Error).message);}}
  async function mutate(path:string,method:string,body:unknown,message:string){if(busy)return false;setBusy(true);try{const r=await api(path,method,body);if(r.relogin){setUser(null);setData(null);setToast("Kod zmieniony. Zaloguj się nowym kodem.");}else{await load(true);setToast(message);}return true;}catch(e){setError((e as Error).message);return false;}finally{setBusy(false);}}
  async function setTaskStatus(task:Task,next:string,note="",values?:number[]){const ok=await mutate("tasks","PATCH",{id:task.id,version:task.version,action:"status",status:next,note,values},next==="done"?"Zadanie wykonane.":next==="issue"?"Problem zgłoszony.":next==="doing"?"Zadanie rozpoczęte.":"Zadanie wróciło na listę.");if(ok){setTemperatureTask(null);setProblemTask(null);setTaskModal(null);}return ok;}
  async function completeTask(task:Task){
    if(busy)return;
    if(readChecklist(task.checklist_meta)?.requiresValue){setTaskModal(null);setTemperatureTask(task);return;}
    await setTaskStatus(task,"done");
  }
  function reportProblem(task:Task){
    if(busy)return;
    if(task.status==="issue"){setTaskModal(task);return;}
    setTaskModal(null);setProblemTask(task);
  }
  function changeDay(delta:number){const d=new Date(selectedDay+"T12:00:00Z");d.setUTCDate(d.getUTCDate()+delta);setSelectedDay(d.toISOString().slice(0,10));}
  const tasks=data?.tasks||[],members=data?.members||[],events=data?.events||[],routines=data?.routines||[];
  const done=tasks.filter(t=>t.status==="done").length,doing=tasks.filter(t=>t.status==="doing").length,remaining=tasks.length-done;
  const progress=tasks.length?Math.round(done/tasks.length*100):0;
  const searchedTasks=tasks.filter(t=>(person==="all"||t.assignee_id===person||(person==="shared"&&!t.assignee_id))&&(!query||[t.title,t.description,readChecklist(t.checklist_meta)?.section||"",t.assignee_name||""].join(" ").toLocaleLowerCase("pl").includes(query.toLocaleLowerCase("pl"))));
  const tasksInCategory=searchedTasks.filter(t=>category==="all"||t.category===category);
  const tasksInStatus=searchedTasks.filter(t=>status==="all"||t.status===status);
  const visibleTasks=tasksInCategory.filter(t=>status==="all"||t.status===status);
  const categoryFilters=[{id:"all",label:"Wszystkie",count:tasksInStatus.length},...categories.filter(c=>["opening","closing","weekly_cleaning"].includes(c.id)||c.id===category||tasks.some(t=>t.category===c.id)).map(c=>({id:c.id,label:c.name,count:tasksInStatus.filter(t=>t.category===c.id).length}))];
  const statusFilters=[{id:"all",label:"Wszystkie statusy"},{id:"todo",label:"Do zrobienia"},{id:"doing",label:"W trakcie"},{id:"done",label:"Wykonane"},{id:"issue",label:"Problemy"}].map(s=>({...s,count:tasksInCategory.filter(t=>s.id==="all"||t.status===s.id).length}));
  const nav=[{id:"today" as Page,label:"Przegląd dnia",icon:LayoutDashboard},{id:"tasks" as Page,label:admin?"Wszystkie zadania":"Moje zadania",icon:ListTodo},...(admin?[{id:"routines" as Page,label:"Cykliczne",icon:Repeat2},{id:"team" as Page,label:"Zespół",icon:Users}]:[]),{id:"history" as Page,label:"Historia aktywności",icon:History}];
  const filteredEvents=events.filter(e=>(historyFilter==="all"||e.action===historyFilter)&&(person==="all"||e.actor_id===person)&&(!query||[e.title,e.actor_name,e.note].join(" ").toLowerCase().includes(query.toLowerCase())));
  function exportHistory(){const rows=[["Data (Warszawa)","Pracownik","Czynność","Zadanie / konto","Notatka"],...filteredEvents.map(e=>[new Date(e.created_at).toLocaleString("pl-PL",{timeZone:"Europe/Warsaw"}),e.actor_name,actionLabels[e.action]||e.action,e.title,e.note])];const csv="\uFEFF"+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(";")).join("\r\n");const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));a.download="cafe-flore-historia-"+today()+".csv";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);setToast("Historia została wyeksportowana.");}

  if(initial)return <main className="initial-loading"><Brand/><LoaderCircle className="spin" size={22}/></main>;
  if(!user)return <main className="login-layout login-simple"><section className="login-panel"><div className="login-card"><Brand/><h1>Logowanie</h1><form onSubmit={login}><label htmlFor="pin">Kod PIN</label><div className="pin-input-wrap"><input id="pin" type="password" inputMode="numeric" autoComplete="off" pattern="[0-9]{3,8}" minLength={3} maxLength={8} required value={pin} onChange={e=>setPin(e.target.value.replace(/\D/g,""))} placeholder="· · ·" autoFocus aria-describedby={loginError?"login-error":undefined}/><ShieldCheck size={20}/></div>{loginError&&<div className="form-error" id="login-error" role="alert">{loginError}</div>}<button className="button primary login-submit" disabled={busy||pin.length<3}>{busy?<LoaderCircle className="spin" size={18}/>:<>Zaloguj się <ArrowRight size={18}/></>}</button></form><p className="login-help">Kod otrzymasz od właściciela kawiarni.</p></div></section>{toast&&<div className="toast" role="status"><Check size={17}/>{toast}</div>}</main>;

  return <div className="app-shell"><aside className="sidebar"><Brand/><div className="workspace-switch"><span className="cafe-icon"><Coffee size={20}/></span><span><strong>{cafeName}</strong><small>Zadania pracowników</small></span><span className="online-dot" title="Zalogowano"/></div><span className="nav-caption">NAWIGACJA</span><nav>{nav.map(n=><button key={n.id} className={page===n.id?"nav-link active":"nav-link"} onClick={()=>{setPage(n.id);setQuery("");setPerson("all");}}><n.icon size={19} strokeWidth={1.7}/><span>{n.label}</span>{n.id==="tasks"&&remaining>0&&<b>{remaining}</b>}</button>)}</nav><div className="sidebar-bottom">{admin&&<button className={page==="settings"?"nav-link active":"nav-link"} onClick={()=>setPage("settings")}><Settings2 size={18}/> Ustawienia</button>}<div className="sidebar-user"><Avatar name={user.name}/><span><strong>{user.name}</strong><small>{admin?"Właściciel kawiarni":"Pracownik kawiarni"}</small></span><button onClick={logout} className="icon-button" aria-label="Wyloguj się"><LogOut size={18}/></button></div></div></aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb"><span>{cafeName}</span><ChevronRight size={13}/><strong>{page==="settings"?"Ustawienia":nav.find(n=>n.id===page)?.label}</strong></div><div className="topbar-right"><span className="role-tag"><ShieldCheck size={14}/>{admin?"Właściciel":"Pracownik"}</span><Avatar name={user.name}/><button className="mobile-logout icon-button" onClick={logout} aria-label="Wyloguj się"><LogOut size={18}/></button></div></header>
    <main className="main-content">{error&&<div className="error-banner" role="alert"><span>{error}</span><button className="text-button" onClick={()=>{setError("");load();}}>Odśwież</button><button className="icon-button" onClick={()=>setError("")} aria-label="Zamknij komunikat"><X size={16}/></button></div>}
    <div className="page-heading"><div><h1>{page==="today"?"Przegląd dnia":page==="tasks"?"Zadania":page==="routines"?"Zadania cykliczne":page==="team"?"Zespół":page==="history"?"Historia aktywności":"Ustawienia"}</h1>{page==="routines"&&<p>Oddzielne zadanie na każdy termin. Edycja i wstrzymanie cyklu obowiązują od następnego dnia.</p>}</div>{admin&&page!=="settings"&&<button className="button primary" onClick={()=>page==="team"?setMemberModal("new"):page==="routines"?setRoutineModal("new"):page==="history"?exportHistory():setTaskModal("new")}>{page==="team"?<><Plus size={18}/> Dodaj pracownika</>:page==="routines"?<><Plus size={18}/> Dodaj cykliczne</>:page==="history"?<><ArrowDownToLine size={17}/> Eksportuj historię</>:<><Plus size={18}/> Dodaj zadanie</>}</button>}</div>

    {(page==="today"||page==="tasks")&&<><div className="day-controls"><div className="date-switch"><button className="icon-button" onClick={()=>changeDay(-1)} aria-label="Poprzedni dzień"><ChevronLeft size={17}/></button><label className="date-picker"><span>{selectedDay===today()?"Dzisiaj, ":""}{dateLabel(selectedDay)}</span><ChevronDown size={14}/><input type="date" aria-label="Wybierz dzień" value={selectedDay} onChange={e=>{if(e.target.value)setSelectedDay(e.target.value);}}/></label><button className="icon-button" onClick={()=>changeDay(1)} aria-label="Następny dzień"><ChevronRight size={17}/></button></div><div className="day-week"><span>{dateLabel(selectedDay,{weekday:"long"})}</span>{selectedDay!==today()&&<button className="text-button" onClick={()=>setSelectedDay(today())}>Dzisiaj</button>}</div></div>
    {page==="today"&&<section className="overview-grid"><div className="metric-card"><span className="metric-icon sage"><ListTodo size={21}/></span><span className="metric-label">Wszystkie zadania</span><strong>{tasks.length}</strong></div><div className="metric-card"><span className="metric-icon moss"><CheckCheck size={21}/></span><span className="metric-label">Wykonane</span><strong>{done}</strong></div><div className="metric-card"><span className="metric-icon peach"><Clock3 size={21}/></span><span className="metric-label">Do wykonania</span><strong>{remaining}<span>{doing} w trakcie</span></strong></div><div className="progress-card"><div><span className="eyebrow">POSTĘP</span><h3>{done} z {tasks.length} zadań</h3></div><div className="progress-ring" style={{"--progress":progress+"%"} as React.CSSProperties}><div><strong>{progress}<small>%</small></strong><span>wykonane</span></div></div></div></section>}
    <div className={"dashboard-grid "+(page==="tasks"?"wide":"")}><section className="tasks-panel"><div className="section-heading"><div><h2>{admin?"Zadania zespołu":"Twoja lista zadań"}<span className="count-tag">{tasks.length}</span></h2></div><label className="search-input"><Search size={17}/><input placeholder="Szukaj zadania…" aria-label="Szukaj zadania" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button aria-label="Wyczyść wyszukiwanie" onClick={()=>setQuery("")}><X size={13}/></button>}</label></div><div className="task-tabs task-category-tabs" aria-label="Grupy zadań">{categoryFilters.map(c=><button key={c.id} className={category===c.id?"selected":""} aria-pressed={category===c.id} onClick={()=>setCategory(c.id)}>{c.label}<span>{c.count}</span></button>)}</div><div className="list-filters"><label className="status-filter"><span>Status</span><select value={status} onChange={e=>setStatus(e.target.value)} aria-label="Filtr statusu zadania">{statusFilters.map(s=><option key={s.id} value={s.id}>{s.label} ({s.count})</option>)}</select></label>{admin&&<label><span>Osoba</span><select value={person} onChange={e=>setPerson(e.target.value)} aria-label="Filtr pracownika"><option value="all">Cały zespół</option><option value="shared">Zadania wspólne</option>{members.filter(m=>m.active).map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label>}<span className="list-filter-count">{visibleTasks.length} na liście{loading&&<LoaderCircle size={13} className="spin"/>}</span></div>
    {loading&&!data?<Empty icon={LoaderCircle} title="Ładujemy plan dnia…">Jeszcze chwila.</Empty>:tasks.length===0?<div className="first-tasks"><div className="empty-illustration"><span className="illustration-paper"><i/><i/><i/><Check size={20}/></span><Sprout size={30}/><span className="illustration-spark">✧</span></div><h3>Brak zadań na ten dzień</h3><p>{admin?"Dodaj zadanie jednorazowe lub ustaw cykl.":"Nie masz przypisanych zadań."}</p>{admin&&<button className="button primary" onClick={()=>setTaskModal("new")}><Plus size={16}/> Dodaj pierwsze zadanie</button>}<div className="first-tasks-bottom"><Sun size={15}/><span>Otwarcie</span><i/><Coffee size={15}/><span>W ciągu dnia</span><i/><Moon size={15}/><span>Zamknięcie</span></div></div>:visibleTasks.length===0?<Empty icon={Search} title="Brak pasujących zadań">Zmień filtry, żeby zobaczyć pozostałe zadania.</Empty>:categories.filter(c=>visibleTasks.some(t=>t.category===c.id)).map(c=><div className="task-group" key={c.id}><div className="task-group-heading"><span className={"group-icon "+c.color}><c.icon size={16}/></span><h3>{c.name}</h3><span>{visibleTasks.filter(t=>t.category===c.id&&t.status==="done").length}/{visibleTasks.filter(t=>t.category===c.id).length}</span>{admin&&<button className="icon-button" aria-label={"Dodaj zadanie: "+c.small} onClick={()=>setTaskModal({...({} as Task),category:c.id,day:selectedDay})}><Plus size={16}/></button>}</div>{visibleTasks.filter(t=>t.category===c.id).map((t,index,group)=><Fragment key={t.id}>{readChecklist(t.checklist_meta)?.section&&readChecklist(t.checklist_meta)?.section!==readChecklist(group[index-1]?.checklist_meta)?.section&&<h4 className="task-subsection">{readChecklist(t.checklist_meta)?.section}</h4>}<div className={"task-row "+(t.status==="done"?"completed":"")} key={t.id}><button className={"task-check "+t.status} aria-label={t.status==="done"?"Cofnij wykonanie: "+t.title:"Oznacz jako wykonane: "+t.title} disabled={busy||(!admin&&t.status==="done"&&t.completed_by!==user.id)} role="checkbox" aria-checked={t.status==="done"} onClick={()=>t.status==="done"?setTaskStatus(t,"todo"):completeTask(t)}>{t.status==="done"?<Check size={15}/>:t.status==="issue"?<AlertTriangle size={12}/>:t.status==="doing"?<span/>:null}</button><button className="task-info" onClick={()=>setTaskModal(t)}><strong>{t.title}{readChecklist(t.checklist_meta)?.required===false&&<span className="optional-badge">Opcjonalne</span>}{t.recurrence_id&&<span className="recurring-badge" title="Zadanie cykliczne"><Repeat2 size={12}/><span>Cykliczne</span></span>}{t.priority==="high"&&t.status!=="done"&&<span className="priority-tag">Ważne</span>}</strong><span>{t.status==="done"?<><CheckCheck size={12}/>{t.completed_name} · {t.completed_at&&shortTime(t.completed_at)}</>:<>{t.time&&<><Clock3 size={12}/>{t.time}<i>·</i></>}{t.assignee_name||"Zadanie wspólne"}{t.status==="doing"&&<b className="doing-label">W trakcie</b>}</>}</span></button>{t.assignee_name&&<Avatar name={t.assignee_name}/>}<button className={"task-problem-button "+(t.status==="issue"?"has-problem":"")} disabled={busy||(!admin&&t.status==="done"&&t.completed_by!==user.id)} aria-label={(t.status==="issue"?"Pokaż problem: ":"Zgłoś problem: ")+t.title} onClick={()=>reportProblem(t)}><AlertTriangle size={13}/> Problem</button><button className="icon-button task-more" aria-label={"Szczegóły: "+t.title} onClick={()=>setTaskModal(t)}><MoreHorizontal size={18}/></button></div></Fragment>)}</div>)}<div className="panel-footer"><span><ShieldCheck size={13}/> Każde wykonanie zapisuje się w historii.</span></div></section>
    {page==="today"&&<aside className="right-column"><section className="activity-panel"><div className="section-heading compact"><h2>Ostatnia aktywność<span className="activity-dot"/></h2><History size={17}/></div>{events.length===0?<div className="activity-empty"><span><History size={24} strokeWidth={1.4}/></span><h3>Brak aktywności</h3><p>Tu zobaczysz ostatnie działania {admin?"zespołu":"na Twoim koncie"}.</p></div>:<div className="activity-list">{events.slice(0,5).map(e=><div className="activity-item" key={e.id}><span className={"activity-bullet "+(e.action==="completed"?"done":"")} >{e.action==="completed"?<Check size={13}/>:<span/>}</span><div><p><strong>{e.actor_name}</strong> {e.action==="completed"?"wykonał(a) zadanie":e.action==="created"?"dodał(a) zadanie":(actionLabels[e.action]||"Zmieniono").toLowerCase()}</p><span className="activity-title">{e.title}</span><small>{dateTime(e.created_at)}</small></div></div>)}</div>}<button className="activity-link" onClick={()=>{setPage("history");setQuery("");setPerson("all");}}>Zobacz całą historię <ArrowUpRight size={15}/></button></section></aside>}</div></>}

    {page==="routines"&&admin&&<section className="routines-panel"><div className="history-toolbar"><label className="search-input"><Search size={17}/><input placeholder="Szukaj na checklistach…" aria-label="Szukaj zadania cyklicznego" value={query} onChange={e=>setQuery(e.target.value)}/></label><span>{routines.filter(r=>r.active&&(!r.ends_on||r.ends_on>=today())).length} aktywnych</span></div>{routines.length===0?<Empty icon={Repeat2} title="Brak zadań cyklicznych">Dodaj checklistę na otwarcie lub zamknięcie.</Empty>:<RoutineChecklists routines={routines} query={query} busy={busy} onEdit={setRoutineModal} onToggle={r=>mutate("routines","PATCH",{id:r.id,version:r.version,action:"toggle"},r.active?"Cykl wstrzymany od jutra.":"Cykl wznowiony od jutra.")}/>}</section>}

    {page==="team"&&admin&&<><div className="team-summary"><span className="team-summary-icon"><Users size={23}/></span><div><strong>{members.filter(m=>m.role==="employee"&&m.active).length} aktywnych pracowników</strong><span>Pracownik widzi swoje zadania oraz zadania wspólne. Ty widzisz cały zespół.</span></div><span className="role-tag"><ShieldCheck size={14}/> Kody PIN są prywatne</span></div><div className="team-grid">{members.map(m=><section className={"member-card "+(!m.active?"inactive":"")} key={m.id}><div className="member-card-top"><Avatar name={m.name} large/><span className={"member-state "+(!m.active?"off":"")}><i/>{m.active?"Aktywne konto":"Nieaktywne"}</span></div><h2>{m.name}</h2><p>{m.role==="admin"?"Właściciel kawiarni":"Pracownik kawiarni"}</p><div className="member-permissions"><ShieldCheck size={15}/>{m.role==="admin"?"Pełny dostęp do kawiarni":"Własny PIN · zadania i historia"}</div><div className="member-card-bottom"><button className="text-button" onClick={()=>setMemberModal(m)}>Edytuj konto <ArrowUpRight size={14}/></button>{m.role!=="admin"&&<button className="text-button muted" disabled={busy} onClick={()=>mutate("members","PATCH",{id:m.id,action:"toggle"},m.active?"Konto dezaktywowane.":"Konto aktywowane.")}>{m.active?"Dezaktywuj":"Aktywuj"}</button>}</div></section>)}<button className="add-member-card" onClick={()=>setMemberModal("new")}><span><Plus size={25}/></span><strong>Dodaj pracownika</strong></button></div></>}

    {page==="history"&&<section className="history-panel"><div className="history-toolbar"><label className="search-input"><Search size={17}/><input placeholder="Szukaj w historii…" aria-label="Szukaj w historii" value={query} onChange={e=>setQuery(e.target.value)}/></label><select aria-label="Filtr rodzaju aktywności" value={historyFilter} onChange={e=>setHistoryFilter(e.target.value)}><option value="all">Wszystkie działania</option><option value="completed">Wykonane zadania</option><option value="problem_reported">Zgłoszone problemy</option><option value="created">Nowe zadania</option><option value="started">Rozpoczęte zadania</option><option value="reopened">Cofnięte wykonania</option></select>{admin&&<select aria-label="Filtr autora aktywności" value={person} onChange={e=>setPerson(e.target.value)}><option value="all">Cały zespół</option>{members.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select>}<span>{filteredEvents.length} wpisów</span></div>{filteredEvents.length===0?<Empty icon={History} title="Brak wpisów">Wpisy pojawią się tu po pierwszych działaniach w aplikacji.</Empty>:<div className="history-table-wrap"><table className="history-table"><thead><tr><th>OSOBA</th><th>AKTYWNOŚĆ</th><th>ZADANIE / KONTO</th><th>KIEDY</th></tr></thead><tbody>{filteredEvents.map(e=><tr key={e.id}><td><span className="history-person"><Avatar name={e.actor_name}/><strong>{e.actor_name}</strong></span></td><td><span className={"history-action "+(e.action==="completed"?"done":"")} >{e.action==="completed"?<CheckCheck size={15}/>:<Circle size={12}/>} {actionLabels[e.action]||e.action}</span></td><td><strong>{e.title}</strong>{e.note&&<p className="history-note">{e.note}</p>}</td><td>{dateTime(e.created_at)}</td></tr>)}</tbody></table></div>}<div className="panel-footer"><span>Ostatnie 300 działań · czas lokalny Warszawy</span><span>Historia wykonania pozostaje po usunięciu zadania.</span></div></section>}

    {page==="settings"&&admin&&<div className="settings-grid"><section className="settings-card"><span className="settings-icon"><Coffee size={24}/></span><h2>Twoja kawiarnia</h2><p>Ta nazwa wyświetla się całemu zespołowi.</p><form onSubmit={async e=>{e.preventDefault();const form=new FormData(e.currentTarget);await mutate("settings","PATCH",{cafeName:form.get("cafeName")},"Nazwa kawiarni zapisana.");}}><label>Nazwa kawiarni<input name="cafeName" defaultValue={cafeName} key={cafeName} required maxLength={80}/></label><button className="button primary" disabled={busy}>Zapisz zmiany</button></form></section><section className="settings-card"><span className="settings-icon peach"><ShieldCheck size={24}/></span><h2>Konto właściciela</h2><p>Imię i kod do zarządzania zespołem. Kod właściciela ma co najmniej 6 cyfr.</p><div className="settings-account"><Avatar name={user.name} large/><div><strong>{user.name}</strong><span>Właściciel kawiarni</span></div></div><button className="button secondary" onClick={()=>setMemberModal(user)}>Zmień nazwę lub kod PIN <ArrowUpRight size={16}/></button></section><section className="settings-info"><Sprout size={25}/><div><h3>Kody i sesje</h3><p>Kody pracowników ustawisz w zakładce Zespół. Zmiana kodu lub dezaktywacja konta wylogowuje tę osobę na wszystkich urządzeniach. Sesja wygasa po 12 godzinach.</p></div></section></div>}
    </main></div>
    <nav className="mobile-nav">{nav.map(n=><button className={page===n.id?"active":""} key={n.id} onClick={()=>{setPage(n.id);setQuery("");setPerson("all");}}><n.icon size={19}/><span>{n.id==="today"?"Dzisiaj":n.id==="history"?"Historia":n.id==="team"?"Zespół":n.id==="routines"?"Cykliczne":"Zadania"}</span></button>)}{admin&&<button className={page==="settings"?"active":""} onClick={()=>setPage("settings")}><Settings2 size={19}/><span>Ustawienia</span></button>}</nav>
    {toast&&<div className="toast" role="status"><Check size={17}/>{toast}</div>}
    {taskModal&&<TaskModal task={taskModal} selectedDay={selectedDay} members={members} admin={Boolean(admin)} busy={busy} user={user} events={events} onClose={()=>setTaskModal(null)} onSave={async payload=>{const existing=taskModal!=="new"&&taskModal.id;const fields=payload as Record<string,unknown>;const recurring=!existing&&fields.recurring;const ok=await mutate(recurring?"routines":"tasks",existing?"PATCH":"POST",recurring?{...fields,startsOn:fields.day}:fields,recurring?"Dodano zadanie cykliczne.":existing?"Zadanie zapisane.":"Zadanie dodane.");if(ok)setTaskModal(null);return ok;}} onStatus={setTaskStatus} onComplete={completeTask} onProblem={reportProblem} onDelete={t=>{setTaskModal(null);setDeleteTask(t);}}/>}
    {routineModal&&<RoutineModal routine={routineModal} members={members} busy={busy} onClose={()=>setRoutineModal(null)} onSave={async payload=>{const ok=await mutate("routines",routineModal==="new"?"POST":"PATCH",payload,routineModal==="new"?"Dodano cykl.":"Zapisano cykl. Zmiany obowiązują od jutra.");if(ok)setRoutineModal(null);return ok;}}/>}
    {memberModal&&<MemberModal member={memberModal} busy={busy} onClose={()=>setMemberModal(null)} onSave={async payload=>{const ok=await mutate("members",memberModal==="new"?"POST":"PATCH",payload,"Konto pracownika zapisane.");if(ok)setMemberModal(null);return ok;}}/>}
    {temperatureTask&&<TemperatureModal task={temperatureTask} busy={busy} onClose={()=>setTemperatureTask(null)} onSave={values=>setTaskStatus(temperatureTask,"done","",values)}/>}
    {problemTask&&<ProblemModal task={problemTask} busy={busy} onClose={()=>setProblemTask(null)} onSave={note=>setTaskStatus(problemTask,"issue",note)}/>}
    {deleteTask&&<Modal title="Usunąć to zadanie?" subtitle={deleteTask.recurrence_id?"Usuwasz tylko zadanie z tego dnia. Cykl i historia pozostaną zapisane.":"Historia wykonania i aktywności pozostanie dostępna."} onClose={()=>setDeleteTask(null)}><p className="delete-title">{deleteTask.title}</p><div className="modal-actions"><button className="button secondary" onClick={()=>setDeleteTask(null)}>Zostaw zadanie</button><button className="button danger" disabled={busy} onClick={async()=>{if(await mutate("tasks","DELETE",{id:deleteTask.id,version:deleteTask.version},"Zadanie usunięte."))setDeleteTask(null);}}><Trash2 size={16}/> Usuń zadanie</button></div></Modal>}
  </div>;
}

function TaskModal({task,selectedDay,members,admin,busy,user,events,onClose,onSave,onStatus,onComplete,onProblem,onDelete}:{task:Task|"new";selectedDay:string;members:User[];admin:boolean;busy:boolean;user:User;events:Event[];onClose:()=>void;onSave:(data:unknown)=>Promise<boolean>;onStatus:(task:Task,status:string)=>Promise<boolean>;onComplete:(task:Task)=>void;onProblem:(task:Task)=>void;onDelete:(task:Task)=>void}) {
  const existing=task!=="new"&&Boolean(task.id),t=task==="new"?null:task;
  const [localError,setLocalError]=useState(""); const [repeat,setRepeat]=useState("once"); const [weekdays,setWeekdays]=useState(127);
  async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();setLocalError("");const f=new FormData(e.currentTarget);if(!existing&&repeat!=="once"&&!weekdays){setLocalError("Wybierz przynajmniej jeden dzień tygodnia.");return;}const isTemperature=f.get("temperature")==="on";const checklist={...readChecklist(t?.checklist_meta),required:f.get("isRequired")==="on",section:String(f.get("section")||"").trim(),requiresValue:isTemperature,valueType:isTemperature?"temperature":null};const ok=await onSave({...Object.fromEntries(f),checklist,...(existing?{id:t!.id,version:t!.version}:{recurring:repeat!=="once",weekdays:repeat==="daily"?127:weekdays})});if(!ok)setLocalError("Nie udało się zapisać. Sprawdź komunikat na stronie i spróbuj ponownie.");}
  return <Modal title={existing?admin?"Szczegóły zadania":"Twoje zadanie":"Nowe zadanie"} subtitle={t?.recurrence_id?"Zmiany dotyczą tylko tego dnia. Harmonogram zmienisz w zakładce Cykliczne.":undefined} onClose={onClose}>{admin?<form onSubmit={save} className="modal-form"><label>Co jest do zrobienia?<input name="title" defaultValue={t?.title||""} placeholder="np. Uzupełnić witrynę z ciastami" required maxLength={150}/></label><label>Dodatkowe wskazówki <span className="optional">opcjonalnie</span><textarea name="description" defaultValue={t?.description||""} placeholder="Co warto wiedzieć przed rozpoczęciem?" maxLength={1500} rows={3}/></label><div className="form-row"><label>{!existing&&repeat!=="once"?"Od kiedy?":"Data"}<input name="day" type="date" defaultValue={t?.day||selectedDay} min={!existing&&repeat!=="once"?today():undefined} readOnly={Boolean(t?.recurrence_id)} required/></label><label>Do której godziny?<input name="time" type="time" defaultValue={t?.time||""}/></label></div><div className="form-row"><label>Etap dnia<select name="category" defaultValue={t?.category||"opening"}>{categories.map(c=><option value={c.id} key={c.id}>{c.small}</option>)}</select></label><label>Priorytet<select name="priority" defaultValue={t?.priority||"normal"}><option value="normal">Zwykły</option><option value="high">Ważne</option></select></label></div>{!existing&&<><label>Powtarzanie<select value={repeat} onChange={e=>setRepeat(e.target.value)}><option value="once">Jednorazowo</option><option value="daily">Codziennie</option><option value="custom">Wybrane dni tygodnia</option></select></label>{repeat==="custom"&&<Weekdays value={weekdays} onChange={setWeekdays}/>}{repeat!=="once"&&<label>Do kiedy? <span className="optional">opcjonalnie</span><input name="endsOn" type="date"/></label>}</>}<label>Kto się tym zajmie?<select name="assigneeId" defaultValue={t?.assignee_id||""}><option value="">Zadanie wspólne · dowolna osoba</option>{members.filter(m=>m.active||m.id===t?.assignee_id).map(m=><option value={m.id} key={m.id} disabled={!m.active}>{m.name}{!m.active?" (nieaktywne konto)":""}</option>)}</select></label><ChecklistOptions meta={readChecklist(t?.checklist_meta)}/>{localError&&<p className="form-error" role="alert">{localError}</p>}<div className="modal-actions">{existing&&<button className="icon-button danger-text" type="button" aria-label="Usuń zadanie" onClick={()=>onDelete(t!)}><Trash2 size={18}/></button>}<button className="button secondary" type="button" onClick={onClose}>Anuluj</button><button className="button primary" disabled={busy}>{busy?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>} {existing?"Zapisz zmiany":"Dodaj zadanie"}</button></div></form>:<div className="task-detail"><h3>{t?.title}</h3><p>{t?.description||"Brak dodatkowych wskazówek."}</p><div className="detail-meta"><span><Clock3 size={15}/>{t?.time||"Bez godziny"}</span><span><Users size={15}/>{t?.assignee_name||"Zadanie wspólne"}</span></div></div>}{existing&&<div className="detail-status"><div><span className={"status-badge "+t!.status}>{t!.status==="done"?<><CheckCheck size={14}/> Wykonane</>:t!.status==="issue"?<><AlertTriangle size={14}/> Zgłoszony problem</>:t!.status==="doing"?<><Clock3 size={14}/> W trakcie</>:<><Circle size={13}/> Do zrobienia</>}</span>{t?.completed_at&&<small>{t.completed_name} · {dateTime(t.completed_at)}</small>}{t?.note&&<p className="detail-note">„{t.note}”</p>}</div>{t!.status!=="done"?<div className="detail-status-actions">{t!.status==="todo"&&<button className="button secondary" disabled={busy} onClick={()=>onStatus(t!,"doing")}>Rozpocznij</button>}{t!.status!=="issue"&&<button className="button secondary problem-detail-button" disabled={busy} onClick={()=>onProblem(t!)}><AlertTriangle size={15}/> Problem</button>}<button className="button primary" disabled={busy} onClick={()=>onComplete(t!)}><Check size={16}/> Wykonane</button></div>:(admin||t!.completed_by===user.id)&&<button className="text-button" disabled={busy} onClick={()=>onStatus(t!,"todo")}>Cofnij wykonanie</button>}</div>}{existing&&events.some(e=>e.task_id===t!.id)&&<div className="task-event-history"><h4>Historia zadania</h4>{events.filter(e=>e.task_id===t!.id).slice(0,8).map(e=><p key={e.id}><span>{actionLabels[e.action]} · {e.actor_name}</span><small>{dateTime(e.created_at)}</small></p>)}</div>}</Modal>;
}
function MemberModal({member,busy,onClose,onSave}:{member:User|"new";busy:boolean;onClose:()=>void;onSave:(data:unknown)=>Promise<boolean>}) {
  const [error,setError]=useState("");const existing=member!=="new";const owner=existing&&member.role==="admin";
  async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();setError("");const f=new FormData(e.currentTarget);const ok=await onSave({...Object.fromEntries(f),...(existing?{id:member.id}:{})});if(!ok)setError("Nie udało się zapisać. Kod może być już zajęty — wybierz inny i spróbuj ponownie.");}
  return <Modal title={existing?"Edytuj konto":"Nowy pracownik"} onClose={onClose}><form className="modal-form" onSubmit={save}><label>Imię i nazwisko<input name="name" defaultValue={existing?member.name:""} required maxLength={80} placeholder="np. Anna Kowalska"/></label><label>{existing?"Nowy kod PIN":"Kod PIN"}{existing&&<span className="optional">zostaw puste, aby zachować obecny</span>}<input name="pin" type="password" inputMode="numeric" autoComplete="new-password" pattern={owner?"[0-9]{6,8}":"[0-9]{3,8}"} minLength={owner?6:3} maxLength={8} required={!existing} placeholder={owner?"6–8 cyfr":"3–8 cyfr, np. 971"}/></label><div className="form-hint"><ShieldCheck size={19}/><p>{owner?"Zmiana kodu wyloguje Cię na wszystkich urządzeniach.":"Przekaż kod tej osobie bezpośrednio. Nie pokazujemy zapisanych kodów — w razie potrzeby ustawisz nowy."}</p></div>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button className="button secondary" type="button" onClick={onClose}>Anuluj</button><button className="button primary" disabled={busy}>{busy?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>} {existing?"Zapisz konto":"Dodaj do zespołu"}</button></div></form></Modal>;
}
function TemperatureModal({task,busy,onClose,onSave}:{task:Task;busy:boolean;onClose:()=>void;onSave:(values:number[])=>Promise<boolean>}){
  const [values,setValues]=useState(["","",""]),[error,setError]=useState("");
  async function save(e:FormEvent){e.preventDefault();setError("");if(values.some(value=>!value.trim()||!Number.isFinite(Number(value.replace(",","."))))){setError("Wpisz trzy temperatury.");return;}if(!await onSave(values.map(value=>Number(value.replace(",",".")))))setError("Nie udało się zapisać odczytów. Spróbuj ponownie.");}
  return <Modal title="Odczyty temperatury" onClose={onClose}><form className="modal-form" onSubmit={save}><p className="completion-task-name">{task.title}</p><fieldset className="temperature-fields"><legend>Temperatury w °C</legend>{temperatureLabels.map((label,index)=><label key={label}>{label}<div className="temperature-input"><input data-autofocus={index===0?true:undefined} type="number" inputMode="decimal" step="any" min={-100} max={100} required value={values[index]} onChange={e=>setValues(previous=>previous.map((value,i)=>i===index?e.target.value:value))}/><span>°C</span></div></label>)}</fieldset>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button secondary" onClick={onClose}>Anuluj</button><button className="button primary" disabled={busy}>{busy?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>} Zapisz odczyty</button></div></form></Modal>;
}
function ProblemModal({task,busy,onClose,onSave}:{task:Task;busy:boolean;onClose:()=>void;onSave:(note:string)=>Promise<boolean>}){
  const [note,setNote]=useState(""),[error,setError]=useState("");
  async function save(e:FormEvent){e.preventDefault();setError("");if(!note.trim()){setError("Opisz problem.");return;}if(!await onSave(note.trim()))setError("Nie udało się zapisać zgłoszenia. Spróbuj ponownie.");}
  const section=readChecklist(task.checklist_meta)?.section;
  return <Modal title="Zgłoś problem" onClose={onClose}><form className="modal-form" onSubmit={save}><p className="completion-task-name">{section?section+" · ":""}{task.title}</p><label>Co jest nie tak?<textarea data-autofocus required maxLength={1500} rows={4} value={note} onChange={e=>setNote(e.target.value)} placeholder="Opisz, co się stało i czego potrzeba."/></label>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button secondary" onClick={onClose}>Anuluj</button><button className="button danger" disabled={busy}>{busy?<LoaderCircle size={16} className="spin"/>:<AlertTriangle size={16}/>} Zapisz zgłoszenie</button></div></form></Modal>;
}
function ChecklistOptions({meta}:{meta:ChecklistMeta|null}){return <div className="checklist-options"><label><input type="checkbox" name="isRequired" defaultChecked={meta?.required!==false}/> Zadanie wymagane</label><label><input type="checkbox" name="temperature" defaultChecked={Boolean(meta?.requiresValue)}/> Zapis trzech temperatur</label><label className="checklist-section">Podgrupa <span className="optional">opcjonalnie, np. Bar lub WC</span><input name="section" defaultValue={meta?.section||""} maxLength={80}/></label></div>;}

function Weekdays({value,onChange}:{value:number;onChange:(value:number)=>void}){
  return <fieldset className="weekdays-field"><legend>Dni tygodnia</legend><div className="weekday-presets"><button type="button" className="text-button" onClick={()=>onChange(127)}>Codziennie</button><button type="button" className="text-button" onClick={()=>onChange(62)}>Pon.–pt.</button><button type="button" className="text-button" onClick={()=>onChange(65)}>Weekend</button></div><div className="weekday-buttons">{weekdaysList.map(d=><button key={d.bit} type="button" aria-pressed={Boolean(value&d.bit)} className={value&d.bit?"chosen":""} onClick={()=>onChange(value^d.bit)}>{d.label}</button>)}</div></fieldset>;
}
function RoutineModal({routine,members,busy,onClose,onSave}:{routine:Routine|"new";members:User[];busy:boolean;onClose:()=>void;onSave:(data:unknown)=>Promise<boolean>}){
  const r=routine==="new"?null:routine;
  const [weekdays,setWeekdays]=useState(r?.weekdays??127),[error,setError]=useState("");
  async function save(e:FormEvent<HTMLFormElement>){
    e.preventDefault();setError("");if(!weekdays){setError("Wybierz przynajmniej jeden dzień tygodnia.");return;}
    const fields=Object.fromEntries(new FormData(e.currentTarget));
    if(fields.endsOn&&String(fields.endsOn)<String(fields.startsOn)){setError("Data końcowa nie może być wcześniejsza od początkowej.");return;}
    if(!r&&String(fields.startsOn)<today()){setError("Nowy cykl może zaczynać się najwcześniej dzisiaj.");return;}
    const isTemperature=fields.temperature==="on";const checklist={...readChecklist(r?.checklist_meta),required:fields.isRequired==="on",section:String(fields.section||"").trim(),requiresValue:isTemperature,valueType:isTemperature?"temperature":null};if(!await onSave({...fields,checklist,weekdays,...(r?{id:r.id,version:r.version}:{})}))setError("Nie udało się zapisać cyklu. Odśwież listę i spróbuj ponownie.");
  }
  return <Modal title={r?"Edytuj zadanie cykliczne":"Nowe zadanie cykliczne"} subtitle={r?"Zmiany obowiązują od następnego dnia. Dotychczasowe wykonania zostają w historii.":"Każdy termin ma osobny status wykonania."} onClose={onClose}><form className="modal-form" onSubmit={save}><label>Nazwa zadania<input name="title" defaultValue={r?.title||""} required maxLength={150} placeholder="np. Uruchomić ekspres"/></label><label>Opis <span className="optional">opcjonalnie</span><textarea name="description" defaultValue={r?.description||""} rows={2} maxLength={1500}/></label><Weekdays value={weekdays} onChange={setWeekdays}/><div className="form-row"><label>Od kiedy?<input name="startsOn" type="date" defaultValue={r?.starts_on||today()} min={r?undefined:today()} required/></label><label>Do kiedy? <span className="optional">opcjonalnie</span><input name="endsOn" type="date" defaultValue={r?.ends_on||""}/></label></div><div className="form-row"><label>Etap dnia<select name="category" defaultValue={r?.category||"opening"}>{categories.map(c=><option key={c.id} value={c.id}>{c.small}</option>)}</select></label><label>Godzina <span className="optional">opcjonalnie</span><input name="time" type="time" defaultValue={r?.time||""}/></label></div><div className="form-row"><label>Przypisanie<select name="assigneeId" defaultValue={r?.assignee_id||""}><option value="">Zadanie wspólne</option>{members.filter(m=>m.active||m.id===r?.assignee_id).map(m=><option value={m.id} key={m.id} disabled={!m.active}>{m.name}{!m.active?" (nieaktywne konto)":""}</option>)}</select></label><label>Priorytet<select name="priority" defaultValue={r?.priority||"normal"}><option value="normal">Zwykły</option><option value="high">Ważne</option></select></label></div><ChecklistOptions meta={readChecklist(r?.checklist_meta)}/>{error&&<p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button type="button" className="button secondary" onClick={onClose}>Anuluj</button><button className="button primary" disabled={busy}>{busy?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>} {r?"Zapisz zmiany":"Dodaj cykl"}</button></div></form></Modal>;
}

function RoutineChecklists({routines,query,busy,onEdit,onToggle}:{routines:Routine[];query:string;busy:boolean;onEdit:(routine:Routine)=>void;onToggle:(routine:Routine)=>Promise<boolean>}){
  const [collapsed,setCollapsed]=useState<Record<string,boolean>>({closing:true,weekly_cleaning:true});
  const filtered=routines.filter(r=>!query||[r.title,r.description,readChecklist(r.checklist_meta)?.section||""].join(" ").toLocaleLowerCase("pl").includes(query.toLocaleLowerCase("pl")));
  if(!filtered.length)return <Empty icon={Search} title="Brak pasujących zadań">Zmień wyszukiwanie.</Empty>;
  return <div className="routine-checklists">{categories.map(c=>{
    const group=filtered.filter(r=>r.category===c.id).sort((a,b)=>(readChecklist(a.checklist_meta)?.sortOrder||0)-(readChecklist(b.checklist_meta)?.sortOrder||0));
    if(!group.length)return null;const hidden=!query&&collapsed[c.id];
    return <section className="routine-category" key={c.id}><button className="routine-category-heading" aria-expanded={!hidden} aria-controls={"routine-group-"+c.id} onClick={()=>setCollapsed(previous=>({...previous,[c.id]:!previous[c.id]}))}><span className={"group-icon "+c.color}><c.icon size={18}/></span><h2>{c.name}</h2><span className="count-tag">{group.length}</span><ChevronDown size={17} className={hidden?"collapsed":""}/></button>{!hidden&&<div className="routine-list" id={"routine-group-"+c.id}>{group.map((r,index)=>{const section=readChecklist(r.checklist_meta)?.section;return <Fragment key={r.id}>{section&&section!==readChecklist(group[index-1]?.checklist_meta)?.section&&<h3 className="routine-subsection">{section}</h3>}<article className={"routine-row "+(!r.active?"paused":"")}><div className="routine-content"><div className="routine-title"><h2>{r.title}</h2>{readChecklist(r.checklist_meta)?.required===false&&<span className="optional-badge">Opcjonalne</span>}<span className={"routine-state "+(r.active?"enabled":"")}>{r.ends_on&&r.ends_on<today()?"Zakończone":r.active?"Aktywne":"Wstrzymane"}</span></div><p><span>{scheduleLabel(r.weekdays)}</span>{r.time&&<><i>·</i><span>{r.time}</span></>}<i>·</i><span>{r.assignee_name||"Zadanie wspólne"}</span></p>{r.ends_on&&<small>Do {dateLabel(r.ends_on,{day:"numeric",month:"short",year:"numeric"})}</small>}</div><div className="routine-actions"><button className="button secondary" onClick={()=>onEdit(r)}>Edytuj</button><button className="text-button" disabled={busy} onClick={()=>onToggle(r)}>{r.active?"Wstrzymaj":"Wznów"}</button></div></article></Fragment>;})}</div>}</section>;
  })}</div>;
}
